from __future__ import annotations

import numpy as np
import sasktran2 as sk

from aliprocessing.cal_db import SimpleInstrument
from aliprocessing.l2.ancillary import Ancillary
from aliprocessing.l2.optical import aerosol_median_radius_db
from aliprocessing.solar import ChannelSolarIrradiance


def test_ancillary_adds_rayleigh_and_solar_irradiance(small_cal_db):
    altitudes = np.arange(0.0, 65001.0, 1000.0)
    geometry = sk.Geometry1D(
        0.6,
        0.0,
        6371000.0,
        altitudes,
        sk.InterpolationMethod.LinearInterpolation,
        sk.GeometryType.Spherical,
    )
    atmo = sk.Atmosphere(geometry, sk.Config(), wavelengths_nm=np.array([745.0]))
    anc = Ancillary(
        altitudes,
        101325.0 * np.exp(-altitudes / 7000.0),
        np.full(len(altitudes), 250.0),
        cal_db=small_cal_db,
    )

    anc.add_to_atmosphere(atmo)

    assert isinstance(atmo["rayleigh"], sk.constituent.Rayleigh)
    # The solar irradiance is averaged through the calibration database's SRF
    solar = atmo["solar_irradiance"]
    assert isinstance(solar, ChannelSolarIrradiance)
    solar.add_to_atmosphere(atmo)
    np.testing.assert_allclose(atmo.storage.solar_irradiance, solar.irradiance[:1])


def test_aerosol_median_radius_db_clamps_single_scatter_albedo():
    db = aerosol_median_radius_db()

    ssa = db._database["xs_scattering"] / db._database["xs_total"]

    assert float(ssa.max()) < 1.0
    assert float(ssa.min()) > 0.0
    np.testing.assert_array_equal(
        db._database["wavelength_nm"],
        [470, 525, 745, 869, 1020, 1230, 1450, 1500, 1550, 1560, 1600, 1650],
    )
    np.testing.assert_array_equal(
        db._database["median_radius"], np.arange(10, 600, 10.0)
    )


def test_aerosol_table_includes_the_default_channels():
    # Interpolating the table between wavelengths misestimates the cross
    # section, so every default channel centre is tabulated
    tabulated = aerosol_median_radius_db()._database["wavelength_nm"].to_numpy()
    assert set(SimpleInstrument().center_wavelengths_nm) <= set(tabulated.tolist())
